compute_enriched_dwpc_GCD.cypher:
// dwpc_GCD for every candidate (gene, disease) pair
// metapath  g -targeted by- C(drug) -indication|drug_investigated_for- D(disease)
// weight    pow( drug_g * target_C * ind_C * dind_D, -0.4 )
// UPDATED 2026-08-06: drug_investigated_for now included alongside indication
// (both approved AND investigational drug-disease links) -- see decision to add
// drug_investigated_for to the graph, TARGET_PRIORITIZER.md §11. No LOO: metapath
// never touches g's disease_protein edge, so there is no label leakage.

// 1) same disease scope as GGD/GPGD (>= 20 seeds) so the join keys line up
MATCH (D:disease)-[:disease_protein]-(seed:protein)
WITH D, count(DISTINCT seed.node_index) AS module_size
WHERE module_size >= 20

// 2) shared-drug metapath + per-node degrees via COUNT{} subqueries
MATCH (g:protein)-[:drug_protein]-(C:drug)-[:indication|drug_investigated_for]-(D)
WITH g.node_index AS gene_index, D.node_index AS disease_index,
     CAST(COUNT { MATCH (g)-[:drug_protein]-() } AS DOUBLE) AS drug_g,
     CAST(COUNT { MATCH (C)-[:drug_protein]-() } AS DOUBLE) AS target_C,
     CAST(COUNT { MATCH (C)-[:indication|drug_investigated_for]-() } AS DOUBLE) AS ind_C,
     CAST(COUNT { MATCH (D)-[:indication|drug_investigated_for]-() } AS DOUBLE) AS dind_D

// 3) degree-weight each path and sum per pair
WITH gene_index, disease_index,
     sum( pow(drug_g * target_C * ind_C * dind_D, -0.4) ) AS dwpc_GCD
RETURN gene_index, disease_index, dwpc_GCD

compute_enriched_dwpc_GGD.cypher:
// dwpc_GGD for every candidate (gene, disease) pair
// metapath g -PPI- m -assoc- D ; weight pow(deg*deg*deg*module, -0.4) ; LOO on g
// The count(DISTINCT) module_size is used ONLY to pick training diseases.
// The weight uses a scalar COUNT{} subquery (mod_raw) so the final sum() has
// no nested aggregation.

// 1) keep diseases with a real module (>= 20 protein seeds)
MATCH (D:disease)-[:disease_protein]-(seed:protein)
WITH D, count(DISTINCT seed.node_index) AS module_size
WHERE module_size >= 20

// 2) expand the metapath from those diseases; per-node degrees via COUNT{} subqueries
MATCH (g:protein)-[:protein_protein]-(m:protein)-[:disease_protein]-(D)
WHERE m.node_index <> g.node_index
WITH g.node_index AS gene_index, D.node_index AS disease_index,
     CAST(COUNT { MATCH (g)-[:protein_protein]-() } AS DOUBLE) AS ppi_g,
     CAST(COUNT { MATCH (m)-[:protein_protein]-() } AS DOUBLE) AS ppi_m,
     CAST(COUNT { MATCH (m)-[:disease_protein]-() } AS DOUBLE) AS assoc_m,
     CAST(COUNT { MATCH (D)-[:disease_protein]-() } AS DOUBLE) AS mod_raw,
     CASE WHEN COUNT { MATCH (g)-[:disease_protein]-(D) } > 0 THEN 1 ELSE 0 END AS g_in_mod

// 3) degree-weight each path (LOO drops g from the module) and sum per pair
WITH gene_index, disease_index,
     sum( pow(ppi_g * ppi_m * assoc_m * (mod_raw - g_in_mod), -0.4) ) AS dwpc_GGD
RETURN gene_index, disease_index, dwpc_GGD

compute_enriched_dwpc_GPGD.cypher:
// dwpc_GPGD for every candidate (gene, disease) pair
// metapath  g -in- P(pathway) -contains- m(gene) -assoc- D(disease)
// weight    pow( path_g * path_P^2 * path_m * assoc_m * mod_D, -0.4 )
//           P sits on two pathway_protein metaedges -> weighted twice
// LOO       m <> g  (m=g would traverse g's own disease_protein edge = leak)
//           AND module-size drops g  (mod_raw - g_in_mod)

// 1) training diseases (>= 20 protein seeds) -- filter only
MATCH (D:disease)-[:disease_protein]-(seed:protein)
WITH D, count(DISTINCT seed.node_index) AS module_size
WHERE module_size >= 20

// 2) shared-pathway metapath + per-node degrees via COUNT{} subqueries
MATCH (g:protein)-[:pathway_protein]-(P:pathway)-[:pathway_protein]-(m:protein)-[:disease_protein]-(D)
WHERE m.node_index <> g.node_index
WITH g.node_index AS gene_index, D.node_index AS disease_index,
     CAST(COUNT { MATCH (g)-[:pathway_protein]-() } AS DOUBLE) AS path_g,
     CAST(COUNT { MATCH (P)-[:pathway_protein]-() } AS DOUBLE) AS path_P,
     CAST(COUNT { MATCH (m)-[:pathway_protein]-() } AS DOUBLE) AS path_m,
     CAST(COUNT { MATCH (m)-[:disease_protein]-() } AS DOUBLE) AS assoc_m,
     CAST(COUNT { MATCH (D)-[:disease_protein]-() } AS DOUBLE) AS mod_raw,
     CASE WHEN COUNT { MATCH (g)-[:disease_protein]-(D) } > 0 THEN 1 ELSE 0 END AS g_in_mod

// 3) degree-weight each path (P twice; LOO on module) and sum per pair
WITH gene_index, disease_index,
     sum( pow(path_g * path_P * path_P * path_m * assoc_m * (mod_raw - g_in_mod), -0.4) ) AS dwpc_GPGD
RETURN gene_index, disease_index, dwpc_GPGD

compute_enriched_guilt_by_association_1.cypher:
// ppi neighbor-overlap features (guilt-by-association):
//   ppi_common_neighbors = |N_PPI(g) ∩ module(D)|
//   ppi_adamic_adar      = Σ_{m in overlap} 1/log(deg_PPI(m))
//   ppi_jaccard          = |overlap| / |N_PPI(g) ∪ module(D)|
// LOO: m <> g, and module excludes g in the Jaccard union (module_size - g_in_mod).
// PPI is stored BOTH directions in this Kuzu build (verified) -> undirected COUNT{} PPI
//   degree is 2x true, so /2.0; WITH DISTINCT collapses the doubled (g,m) edge.
//   disease_protein is single-stored -> no correction.

// 1) training diseases (>= 20 seeds)
MATCH (D:disease)-[:disease_protein]-(seed:protein)
WITH D, count(DISTINCT seed.node_index) AS module_size
WHERE module_size >= 20

// 2) g's PPI neighbors that are module genes of D (collapse the doubled PPI edge)
MATCH (g:protein)-[:protein_protein]-(m:protein)-[:disease_protein]-(D)
WHERE m.node_index <> g.node_index
WITH DISTINCT g, m, D, module_size

// 3) true PPI degree of each shared neighbor m
WITH g, D, module_size, m,
     (CAST(COUNT { MATCH (m)-[:protein_protein]-() } AS DOUBLE) / 2.0) AS deg_m

// 4) aggregate over shared neighbors; carry per-(g,D) scalars as grouping keys
WITH g.node_index AS gene_index, D.node_index AS disease_index, module_size,
     (CAST(COUNT { MATCH (g)-[:protein_protein]-() } AS DOUBLE) / 2.0)               AS ppi_deg_g,
     (CASE WHEN COUNT { MATCH (g)-[:disease_protein]-(D) } > 0 THEN 1 ELSE 0 END)    AS g_in_mod,
     count(m)                                                                         AS ppi_common_neighbors,
     sum(CASE WHEN deg_m > 1.0 THEN 1.0 / log(deg_m) ELSE 0.0 END)                    AS ppi_adamic_adar

// 5) Jaccard from the union size (module excludes g via g_in_mod)
WITH gene_index, disease_index, ppi_common_neighbors, ppi_adamic_adar,
     (ppi_deg_g + (module_size - g_in_mod) - ppi_common_neighbors) AS union_size
RETURN gene_index, disease_index,
       ppi_common_neighbors,
       ppi_adamic_adar,
       CASE WHEN union_size > 0 THEN ppi_common_neighbors * 1.0 / union_size ELSE 0.0 END AS ppi_jaccard
